# custom_reports.py
# ------------------------------------------------------------
# Reports on demand: choose a report, a date range and the parameters, look at
# it on screen, export it to Excel. Read-only: nothing here writes to the database.
#
#   GET /reports/custom/options   -> projects, report types (reports.view)
#   GET /reports/custom           -> the report as JSON, first rows only (reports.view)
#   GET /reports/custom/export    -> the whole report as .xlsx (reports.export)
#
# Reports (type=):
#   activity         entries / exits in the date range (optionally one project, one action)
#   project_summary  per project: visitors, inside now, entries, exits, distinct visitors
#   visitors         the visitors of one project (or all), with approval and expiry dates
#   expiry           expired / expiring approvals, classification (סב"ט) or visa dates
# Dates travel as ISO (2026-12-31) and are shown as 31.12.2026.
# Log rows marked as duplicates (see dedupe.py) are left out.
# ------------------------------------------------------------

import io
from datetime import date, datetime, timedelta
from typing import Dict, List, Optional

from fastapi import APIRouter, Depends, HTTPException, Query
from fastapi.responses import StreamingResponse
from openpyxl import Workbook
from openpyxl.styles import Alignment, Font
from openpyxl.utils import get_column_letter
from sqlalchemy import func
from sqlalchemy.orm import Session

from . import database, models
from .dedupe import norm_action, visible
from .dependencies import require_permission
from .reports import _HEADER_FILL, _HEADER_FONT, _TITLE_FONT, action_label
from .routes_locations import (
    DEFAULT_EXPIRY_DAYS,
    KEY_EXPIRY_DAYS,
    NO_PROJECT,
    get_int_setting,
)
from .routes_reports import _attachment
from .visitor_extras import (
    CLASSIFICATION_EXPIRY_ALIASES,
    INFOSEC_EXPIRY_ALIASES,
    INFOSEC_KEY,
    VISA_EXPIRY_ALIASES,
    find_key,
    get_project,
    get_value,
    parse_date,
    today_local,
)

router = APIRouter(prefix="/reports/custom", tags=["reports"])

PREVIEW_ROWS = 500
EXPORT_ROWS = 100000

TYPES = {
    "activity": "כניסות ויציאות לפי תאריכים",
    "project_summary": "סיכום לפי פרויקט",
    "visitors": "רשימת מבקרים לפי פרויקט",
    "expiry": "דוח תוקף (פגי תוקף, סב\"ט, אישורים)",
}
EXPIRY_FIELDS = {
    "all": ("כל סוגי התוקף", None),
    "infosec": ("תוקף אישור (אבטחת מידע)", INFOSEC_EXPIRY_ALIASES),
    "classification": ('תוקף סיווג (סב"ט)', CLASSIFICATION_EXPIRY_ALIASES),
    "visa": ("תוקף ויזה", VISA_EXPIRY_ALIASES),
}
STATUS_LABEL = {"expired": "פג תוקף", "expiring": "עומד לפוג", "ok": "בתוקף"}


def dmy(d) -> str:
    if d is None:
        return ""
    return d.strftime("%d.%m.%Y")


def dmy_time(t) -> str:
    return t.strftime("%d.%m.%Y %H:%M:%S") if t else ""


def _date_param(value: Optional[str], name: str) -> Optional[date]:
    if not value:
        return None
    try:
        return date.fromisoformat(value)
    except ValueError:
        raise HTTPException(status_code=400, detail="תאריך לא תקין ב'{}'".format(name))


def _project_of(visitor) -> str:
    return get_project(visitor.properties or {}) or NO_PROJECT


def _project_order(name: str):
    return (name == NO_PROJECT, name)


# ---- the reports ----------------------------------------------------------------


def _visitors_in(db: Session, project: Optional[str]) -> List[models.Visitor]:
    out = []
    for v in db.query(models.Visitor).order_by(models.Visitor.name).all():
        if project and _project_of(v) != project:
            continue
        out.append(v)
    return out


def _range(date_from: Optional[date], date_to: Optional[date]):
    """Default: the last 30 days. Returns (from, to, start_dt, end_dt) with `to` inclusive."""
    today = today_local()
    d_to = date_to or today
    d_from = date_from or (d_to - timedelta(days=29))
    if d_from > d_to:
        raise HTTPException(status_code=400, detail="'מתאריך' מאוחר מ'עד תאריך'")
    return d_from, d_to, datetime.combine(d_from, datetime.min.time()), datetime.combine(
        d_to + timedelta(days=1), datetime.min.time()
    )


def _logs(db: Session, start_dt, end_dt):
    return visible(
        db.query(models.VisitorLog)
        .filter(models.VisitorLog.timestamp >= start_dt)
        .filter(models.VisitorLog.timestamp < end_dt)
    )


def report_activity(db, date_from, date_to, project, action):
    d_from, d_to, start_dt, end_dt = _range(date_from, date_to)
    wanted = ("entry", "exit") if action in (None, "", "both") else None
    vis = {v.dbid: v for v in _visitors_in(db, project)}
    rows = []
    for log in _logs(db, start_dt, end_dt).order_by(models.VisitorLog.timestamp.desc()):
        v = vis.get(log.visitor_dbid)
        if v is None:
            continue
        a = norm_action(log.action)
        if wanted is not None and a not in wanted:
            continue
        if action in ("entry", "exit") and a != action:
            continue
        rows.append(
            [dmy_time(log.timestamp), v.name, v.visitorid, _project_of(v), action_label(log.action)]
        )
    return {
        "title": TYPES["activity"],
        "subtitle": ["תקופה: {} - {}".format(dmy(d_from), dmy(d_to))]
        + (["פרויקט: " + project] if project else []),
        "columns": ["תאריך ושעה", "שם", "מספר זיהוי", "פרויקט", "פעולה"],
        "rows": rows,
    }


def report_project_summary(db, date_from, date_to, project):
    d_from, d_to, start_dt, end_dt = _range(date_from, date_to)
    stats: Dict[str, dict] = {}
    by_id = {}
    for v in _visitors_in(db, project):
        p = _project_of(v)
        s = stats.setdefault(p, {"vis": 0, "inside": 0, "en": 0, "ex": 0, "uniq": set()})
        s["vis"] += 1
        if v.inside:
            s["inside"] += 1
        by_id[v.dbid] = p
    for log in _logs(db, start_dt, end_dt):
        p = by_id.get(log.visitor_dbid)
        if p is None:
            continue
        a = norm_action(log.action)
        if a == "entry":
            stats[p]["en"] += 1
            stats[p]["uniq"].add(log.visitor_dbid)
        elif a == "exit":
            stats[p]["ex"] += 1
    rows = []
    tot = [0, 0, 0, 0, 0]
    for p in sorted(stats, key=_project_order):
        s = stats[p]
        vals = [s["vis"], s["inside"], s["en"], s["ex"], len(s["uniq"])]
        rows.append([p] + vals)
        tot = [a + b for a, b in zip(tot, vals)]
    if len(rows) > 1:
        rows.append(['סה"כ'] + tot)
    return {
        "title": TYPES["project_summary"],
        "subtitle": ["תקופה: {} - {}".format(dmy(d_from), dmy(d_to))]
        + (["פרויקט: " + project] if project else []),
        "columns": ["פרויקט", "מבקרים רשומים", "בפנים כרגע", "כניסות", "יציאות", "מבקרים שונים שנכנסו"],
        "rows": rows,
    }


def report_visitors(db, project):
    last_entry = {
        d: t
        for d, t in visible(
            db.query(models.VisitorLog.visitor_dbid, func.max(models.VisitorLog.timestamp)).filter(
                func.lower(func.trim(models.VisitorLog.action)) == "entry"
            )
        )
        .group_by(models.VisitorLog.visitor_dbid)
        .all()
    }
    rows = []
    vis = sorted(_visitors_in(db, project), key=lambda v: (_project_order(_project_of(v)), v.name or ""))
    for v in vis:
        props = v.properties or {}
        rows.append(
            [
                v.name,
                v.visitorid,
                _project_of(v),
                get_value(props, INFOSEC_KEY) or "",
                dmy(parse_date(get_value(props, INFOSEC_EXPIRY_ALIASES))),
                dmy(parse_date(get_value(props, CLASSIFICATION_EXPIRY_ALIASES))),
                "בפנים" if v.inside else "בחוץ",
                dmy_time(last_entry.get(v.dbid)),
            ]
        )
    return {
        "title": TYPES["visitors"],
        "subtitle": ["פרויקט: " + (project or "כל הפרויקטים")],
        "columns": ["שם", "מספר זיהוי", "פרויקט", "אבטחת מידע", "תוקף אישור", 'תוקף סב"ט', "מצב", "כניסה אחרונה"],
        "rows": rows,
    }


def report_expiry(db, date_from, date_to, project, field, status, warn_days):
    if field not in EXPIRY_FIELDS:
        raise HTTPException(status_code=400, detail="סוג תוקף לא מוכר")
    if status not in (None, "", "all", "expired", "expiring", "ok"):
        raise HTTPException(status_code=400, detail="סטטוס לא מוכר")
    if date_from and date_to and date_from > date_to:
        raise HTTPException(status_code=400, detail="'מתאריך' מאוחר מ'עד תאריך'")
    today = today_local()
    if warn_days is None:
        warn_days = get_int_setting(db, KEY_EXPIRY_DAYS, DEFAULT_EXPIRY_DAYS)
    groups = (
        [(k, v[0], v[1]) for k, v in EXPIRY_FIELDS.items() if k != "all"]
        if field == "all"
        else [(field, EXPIRY_FIELDS[field][0], EXPIRY_FIELDS[field][1])]
    )
    rows = []
    unreadable = 0
    for v in _visitors_in(db, project):
        props = v.properties or {}
        for _k, label, aliases in groups:
            key = find_key(props, aliases)
            if key is None:
                continue
            d = parse_date(props[key])
            if d is None:
                unreadable += 1
                continue
            days_left = (d - today).days
            st = "expired" if days_left < 0 else ("expiring" if days_left <= warn_days else "ok")
            if status in ("expired", "expiring", "ok") and st != status:
                continue
            if date_from and d < date_from:
                continue
            if date_to and d > date_to:
                continue
            rows.append(
                [
                    v.name,
                    v.visitorid,
                    _project_of(v),
                    label,
                    dmy(d),
                    days_left,
                    STATUS_LABEL[st],
                    get_value(props, INFOSEC_KEY) or "",
                ]
            )
    rows.sort(key=lambda r: (r[5], r[0] or ""))
    sub = ["נכון לתאריך: " + dmy(today), "סוג תוקף: " + EXPIRY_FIELDS[field][0]]
    if status in ("expired", "expiring", "ok"):
        sub.append("סטטוס: {}{}".format(STATUS_LABEL[status], " (עד {} ימים)".format(warn_days) if status == "expiring" else ""))
    if date_from or date_to:
        sub.append("תאריך תוקף בין {} ל-{}".format(dmy(date_from) or "...", dmy(date_to) or "..."))
    if project:
        sub.append("פרויקט: " + project)
    if unreadable:
        sub.append("{} ערכי תוקף לא נקראו (תאריך לא תקין) ולא נכללו".format(unreadable))
    return {
        "title": TYPES["expiry"],
        "subtitle": sub,
        "columns": ["שם", "מספר זיהוי", "פרויקט", "סוג תוקף", "תאריך תוקף", "ימים לתוקף", "סטטוס", "אבטחת מידע"],
        "rows": rows,
    }


def build_report(
    db: Session,
    type: str,
    date_from: Optional[str] = None,
    date_to: Optional[str] = None,
    project: Optional[str] = None,
    action: Optional[str] = None,
    field: str = "all",
    status: Optional[str] = None,
    warn_days: Optional[int] = None,
) -> dict:
    d_from = _date_param(date_from, "מתאריך")
    d_to = _date_param(date_to, "עד תאריך")
    project = (project or "").strip() or None
    if type == "activity":
        return report_activity(db, d_from, d_to, project, action)
    if type == "project_summary":
        return report_project_summary(db, d_from, d_to, project)
    if type == "visitors":
        return report_visitors(db, project)
    if type == "expiry":
        return report_expiry(db, d_from, d_to, project, field or "all", status, warn_days)
    raise HTTPException(status_code=400, detail="סוג דוח לא מוכר")


# ---- Excel ----------------------------------------------------------------------


def build_xlsx(report: dict) -> bytes:
    wb = Workbook()
    ws = wb.active
    ws.title = "דוח"
    ws.sheet_view.rightToLeft = True
    ws["A1"] = report["title"]
    ws["A1"].font = _TITLE_FONT
    r = 2
    for line in report["subtitle"] + ["הופק: " + datetime.now().strftime("%d.%m.%Y %H:%M")]:
        ws.cell(row=r, column=1, value=line).font = Font(size=10, color="555555")
        r += 1
    r += 1
    head = r
    for c, name in enumerate(report["columns"], start=1):
        cell = ws.cell(row=head, column=c, value=name)
        cell.fill = _HEADER_FILL
        cell.font = _HEADER_FONT
        cell.alignment = Alignment(horizontal="right")
    widths = [len(str(c)) + 4 for c in report["columns"]]
    for row in report["rows"][:EXPORT_ROWS]:
        r += 1
        for c, value in enumerate(row, start=1):
            ws.cell(row=r, column=c, value=value).alignment = Alignment(horizontal="right")
            widths[c - 1] = min(46, max(widths[c - 1], len(str(value)) + 2))
    for c, w in enumerate(widths, start=1):
        ws.column_dimensions[get_column_letter(c)].width = max(12, w)
    ws.freeze_panes = ws.cell(row=head + 1, column=1)
    if report["rows"]:
        ws.auto_filter.ref = "A{}:{}{}".format(head, get_column_letter(len(report["columns"])), r)
    buf = io.BytesIO()
    wb.save(buf)
    return buf.getvalue()


